const electron=require('electron'),{app,BrowserWindow}=electron,fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict')
const {HtmlVisualEditors,WORLD}=require('../../desktop/services/html-visual-editor.cjs')
const out=path.resolve(__dirname,'../../qa-artifacts/html-editor-region');fs.mkdirSync(out,{recursive:true});const work=fs.mkdtempSync(path.join(out,'run-'))
app.setPath('userData',path.join(work,'profile'));app.disableHardwareAcceleration()
const delay=ms=>new Promise(r=>setTimeout(r,ms))
async function main(){
 await app.whenReady()
 const win=new BrowserWindow({show:false,width:1000,height:800,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false,offscreen:true}}),wc=win.webContents
 const js=code=>wc.executeJavaScriptInIsolatedWorld(WORLD,[{code}]),page=code=>wc.executeJavaScript(code)
 const file=path.join(work,'region.html'),source='<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;font:18px sans-serif}.spacer{height:400px}#grid{margin:20px;display:grid;grid-template-columns:1fr 1fr;gap:20px;height:400px;background:#ddeeff}article{background:#fff;padding:20px}footer{height:800px}</style></head><body><div class="spacer"></div><section id="grid"><article><h2>经营指标</h2><p>左侧已有内容</p></article></section><footer></footer></body></html>'
 fs.writeFileSync(file,source);await win.loadFile(file)
 await js(`globalThis.attach=Element.prototype.attachShadow;Element.prototype.attachShadow=function(o){const r=attach.call(this,o);globalThis.editorRoot=r;return r};true`)
 const manager=new HtmlVisualEditors(electron),entry=await manager.start({conversationId:'region',file,view:win,roots:[work],workspace:work,window:win}),s=manager.get('region',entry.sessionId);clearInterval(s.timer)
 await page('scrollTo(0,300)');await delay(50)
 const drag=async(x,y,x2,y2)=>{wc.sendInputEvent({type:'mouseMove',x,y});wc.sendInputEvent({type:'mouseDown',button:'left',clickCount:1,x,y});wc.sendInputEvent({type:'mouseMove',x:x2,y:y2});wc.sendInputEvent({type:'mouseUp',button:'left',clickCount:1,x:x2,y:y2});await delay(80)}
 // Ordinary drag must retain element multi-selection.
 await drag(30,130,470,280)
 assert.match(await js(`editorRoot.querySelector('.selection').textContent`),/已选 2 个元素/)
 assert.equal(await js(`editorRoot.querySelector('.region-surface').hidden`),true)
 await manager.call(s,'run','region')
 assert.equal(await js(`editorRoot.querySelector('.region-surface').hidden`),false)
 await drag(550,150,900,400)
 const panel=await js(`({visible:!editorRoot.querySelector('[data-panel=ai]').hidden,placeholder:editorRoot.querySelector('.ai').placeholder,textHidden:editorRoot.querySelector('.text-tools').hidden,blockHidden:editorRoot.querySelector('.block-tools').hidden,region:editorRoot.querySelector('.marquee').getBoundingClientRect().toJSON()})`)
 assert.ok(panel.visible&&panel.textHidden&&panel.blockHidden);assert.match(panel.placeholder,/添加/);assert.equal(panel.region.width,350)
 // The document position stays fixed while scrolling; screenshot follows the visible region.
 await page('scrollBy(0,40)');await delay(50)
 assert.equal(await js(`editorRoot.querySelector('.marquee').getBoundingClientRect().y`),110)
 fs.writeFileSync(path.join(out,'region-ai.png'),(await wc.capturePage()).toPNG())
 await js(`editorRoot.querySelector('.ai').value='新增一张与左侧同样样式的会员分析卡片';editorRoot.querySelector('.ai').dispatchEvent(new Event('input'));editorRoot.querySelector('[data-action=draft]').click();true`)
 await manager.flush(s)
 assert.equal(s.deliveries.length,1);const delivery=s.deliveries[0];assert.equal(delivery.send,false);assert.equal(delivery.attachments[0].path,file);assert.deepEqual(delivery.attachments.map(a=>a.type),['html','png'])
 const metadata=JSON.parse(fs.readFileSync(path.join(path.dirname(delivery.attachments[1].path),'选区详情.json'),'utf8'))
 assert.deepEqual(metadata.region.rect,{x:550,y:450,width:350,height:250});assert.equal(metadata.targets.length,0);assert.equal(metadata.region.container.tag,'section');assert.equal(metadata.region.container.layout.display,'grid');assert.match(metadata.region.neighbors[0].text,/经营指标/);assert.equal(metadata.region.capturedViewportRect.y,110)
 const context=manager.contextForAttachment('region',delivery.attachments[1].path,work);assert.match(context,/新增内容/);assert.match(context,/CSS 像素/);assert.match(context,/经营指标/)
 const image=electron.nativeImage.createFromPath(delivery.attachments[1].path),size=image.getSize(),full=electron.nativeImage.createFromBuffer((await wc.capturePage()).toPNG()).getSize(),scale=full.width/(await page('innerWidth'))
 assert.ok(Math.abs(size.width-350*scale)<=2&&Math.abs(size.height-250*scale)<=2,JSON.stringify({size,scale}))
 const pixel=image.toBitmap();assert.deepEqual([...pixel.subarray(0,3)],[255,238,221]);assert.deepEqual([...pixel.subarray(Math.floor(size.width*size.height/2)*4,Math.floor(size.width*size.height/2)*4+3)],[255,238,221])
 assert.ok(!fs.readdirSync(path.dirname(delivery.attachments[1].path)).some(f=>f.endsWith('.md')));assert.equal(fs.readFileSync(file,'utf8'),source)
 await js(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));true`)
 assert.equal(await js(`editorRoot.querySelector('.marquee').hidden`),true)
 await manager.call(s,'run','region');await js(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));true`);assert.equal(await js(`editorRoot.querySelector('.region-surface').hidden`),true)
 await js(`__stableHtmlEditor.choose('h2');true`);assert.equal(await js(`editorRoot.querySelector('.text-tools').hidden`),false)
 await manager.event(s,{id:999,type:'ai',prompt:'invalid',targets:[],region:{kind:'region',rect:{x:0,y:0,width:-1,height:20}}});assert.equal(s.deliveries.length,1);assert.match(await js(`editorRoot.querySelector('.error').textContent`),/区域位置无效/)
 await manager.stop('region',entry.sessionId)
 fs.writeFileSync(path.join(out,'result.json'),JSON.stringify({passed:true,panel,region:metadata.region,size,checks:['ordinary drag multi-select','blank region draft','scrolled document coordinates','container and neighbor context','clean cropped screenshot pixels','HTML plus PNG without Markdown','escape and original text tools','invalid region rejected','original HTML unchanged']},null,2));win.destroy();console.log('HTML_EDITOR_REGION_PASSED');app.exit(0)
}
main().catch(e=>{console.error(e.stack);app.exit(1)})
